package com.wanyuecity.energy.power.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.wanyuecity.energy.core.BizException;import com.wanyuecity.energy.power.entity.PowerTopologyNode;import com.wanyuecity.energy.power.mapper.PowerTopologyNodeMapper;import com.wanyuecity.energy.power.service.dto.*;import com.wanyuecity.energy.stall.mapper.StallMapper;import com.wanyuecity.energy.system.mapper.BusinessDictionaryMapper;import com.wanyuecity.energy.system.mapper.PowerSwitchSpecificationMapper;import lombok.RequiredArgsConstructor;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;
@Service @RequiredArgsConstructor public class PowerTopologyService {
 private final PowerTopologyNodeMapper mapper;private final PowerSwitchSpecificationMapper switchMapper;private final BusinessDictionaryMapper dictionaryMapper;private final StallMapper stallMapper;
 public List<PowerTopologyNodeView> tree(){List<PowerTopologyNode> rows=mapper.selectList(new LambdaQueryWrapper<PowerTopologyNode>().orderByAsc(PowerTopologyNode::getSortOrder).orderByAsc(PowerTopologyNode::getId));Map<Long,PowerTopologyNodeView> views=rows.stream().map(this::view).collect(Collectors.toMap(PowerTopologyNodeView::getId,Function.identity(),(a,b)->a,LinkedHashMap::new));List<PowerTopologyNodeView> roots=new ArrayList<>();for(PowerTopologyNode row:rows){PowerTopologyNodeView v=views.get(row.getId());PowerTopologyNodeView parent=row.getParentId()==null?null:views.get(row.getParentId());if(parent==null)roots.add(v);else parent.getChildren().add(v);}return roots;}
 @Transactional public PowerTopologyNodeView create(PowerTopologyNodeRequest r){validate(r,null);PowerTopologyNode n=new PowerTopologyNode();apply(n,r);mapper.insert(n);return view(n);}
 @Transactional public PowerTopologyNodeView update(Long id,PowerTopologyNodeRequest r){PowerTopologyNode n=require(id);validate(r,id);if(r.getParentId()!=null&&isDescendant(id,r.getParentId()))throw BizException.badRequest("不能把节点移动到自己的下级");apply(n,r);mapper.updateById(n);return view(n);}
 @Transactional public void delete(Long id){require(id);if(mapper.selectCount(new LambdaQueryWrapper<PowerTopologyNode>().eq(PowerTopologyNode::getParentId,id))>0)throw BizException.badRequest("该节点仍有下级，请先移动或删除下级节点");mapper.deleteById(id);}
 private boolean isDescendant(Long id,Long candidate){Set<Long> seen=new HashSet<>();Long current=candidate;while(current!=null&&seen.add(current)){if(id.equals(current))return true;PowerTopologyNode n=mapper.selectById(current);current=n==null?null:n.getParentId();}return false;}
 private void validate(PowerTopologyNodeRequest r,Long id){if(r.getParentId()!=null&&mapper.selectById(r.getParentId())==null)throw BizException.badRequest("上级节点不存在");if(mapper.selectCount(new LambdaQueryWrapper<PowerTopologyNode>().eq(PowerTopologyNode::getNodeCode,r.getNodeCode().trim()).ne(id!=null,PowerTopologyNode::getId,id))>0)throw BizException.badRequest("节点编码不可重复");if(dictionaryMapper.selectCount(new LambdaQueryWrapper<com.wanyuecity.energy.system.entity.BusinessDictionary>().eq(com.wanyuecity.energy.system.entity.BusinessDictionary::getDictType,"POWER_NODE_TYPE").eq(com.wanyuecity.energy.system.entity.BusinessDictionary::getItemValue,r.getNodeType()).eq(com.wanyuecity.energy.system.entity.BusinessDictionary::getStatus,1))==0)throw BizException.badRequest("请选择有效的节点类型");if(r.getSwitchSpecificationId()!=null&&switchMapper.selectById(r.getSwitchSpecificationId())==null)throw BizException.badRequest("开关规格不存在");if(r.getStatus()!=null&&r.getStatus()!=0&&r.getStatus()!=1)throw BizException.badRequest("状态只能是启用或停用");}
 private void apply(PowerTopologyNode n,PowerTopologyNodeRequest r){BeanUtils.copyProperties(r,n);n.setNodeCode(r.getNodeCode().trim());n.setNodeName(r.getNodeName().trim());if(n.getSortOrder()==null)n.setSortOrder(0);if(n.getStatus()==null)n.setStatus(1);}
 private PowerTopologyNode require(Long id){PowerTopologyNode n=mapper.selectById(id);if(n==null)throw BizException.notFound("配电节点不存在");return n;}
 private PowerTopologyNodeView view(PowerTopologyNode n){PowerTopologyNodeView v=new PowerTopologyNodeView();BeanUtils.copyProperties(n,v);if(n.getSwitchSpecificationId()!=null){var s=switchMapper.selectById(n.getSwitchSpecificationId());if(s!=null){v.setSwitchSpecificationName((s.getBrand()==null?"":s.getBrand()+" ")+s.getSwitchModel());v.setSwitchRatedCurrentA(s.getRatedCurrentA());}}var d=dictionaryMapper.selectOne(new LambdaQueryWrapper<com.wanyuecity.energy.system.entity.BusinessDictionary>().eq(com.wanyuecity.energy.system.entity.BusinessDictionary::getDictType,"POWER_NODE_TYPE").eq(com.wanyuecity.energy.system.entity.BusinessDictionary::getItemValue,n.getNodeType()).last("LIMIT 1"));v.setNodeTypeName(d==null?n.getNodeType():d.getItemLabel());if(n.getStallId()!=null){var s=stallMapper.selectById(n.getStallId());if(s!=null)v.setStallCode(s.getStallCode());}return v;}
}
